import { createGate, QuotaExceededError } from './src/index.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let randSeed = 12345;
function rnd() {
  randSeed = (randSeed * 1103515245 + 12345) & 0x7fffffff;
  return randSeed / 0x7fffffff;
}

function runOnce(seed) {
  randSeed = seed;
  const root = createGate({ limit: 3, windowMs: 20, maxWaitMs: 60 });
  const mid = createGate({ limit: 2, windowMs: 35, maxWaitMs: 60, parent: root });
  const leaf = createGate({ limit: 1, windowMs: 50, maxWaitMs: 60, parent: mid });
  const gates = [root, mid, leaf];
  const inflight = [];
  let calls = 0;
  const terminals = { granted: 0, refused: 0, expired: 0, cancelled: 0 };
  const acs = new Set();
  let ops = 0;

  function check(label) {
    for (const g of gates) {
      const s = g.stats();
      for (const k of ['inFlight', 'waiting', 'granted', 'refused', 'expired', 'cancelled', 'reserved']) {
        if (!Number.isFinite(s[k]) || s[k] < 0) throw new Error(`${label}: bad ${k}=${s[k]}`);
      }
    }
  }

  async function oneCall() {
    const g = gates[Math.floor(rnd() * 3)];
    const units = 1 + Math.floor(rnd() * 4);
    const useSignal = rnd() < 0.4;
    const ac = useSignal ? new AbortController() : null;
    if (ac) acs.add(ac);
    calls += 1;
    let p;
    try {
      p = g.acquire(units, ac?.signal);
    } catch (e) {
      calls -= 1;
      return;
    }
    p.then(
      (h) => {
        terminals.granted += 1;
        inflight.push(h);
      },
      (e) => {
        terminals[e.code === 'QUOTA_EXCEEDED' ? 'refused' : e.code === 'WAIT_EXPIRED' ? 'expired' : 'cancelled'] += 1;
      },
    );
    if (ac && rnd() < 0.7) {
      setTimeout(() => {
        ac.abort();
        acs.delete(ac);
      }, Math.floor(rnd() * 90));
    }
  }

  return (async () => {
    for (let i = 0; i < 60; i++) {
      const n = 1 + Math.floor(rnd() * 3);
      for (let j = 0; j < n; j++) await oneCall();
      ops += 1;
      await sleep(Math.floor(rnd() * 25));
      if (inflight.length > 0 && rnd() < 0.6) {
        const k = Math.floor(rnd() * Math.min(inflight.length, 3));
        for (let j = 0; j <= k; j++) {
          const h = inflight.shift();
          h.release();
          h.release();
        }
      }
      if (rnd() < 0.1) {
        try {
          root.updateLimit(1 + Math.floor(rnd() * 5));
        } catch {}
      }
      check('mid' + ops);
    }
    await sleep(400);
    for (const ac of acs) ac.abort();
    await sleep(200);
    check('end');
    const total = terminals.granted + terminals.refused + terminals.expired + terminals.cancelled;
    if (total !== calls) {
      throw new Error(`seed ${seed}: UNSETTLED calls=${calls} terminals=${JSON.stringify(terminals)}`);
    }
    let waiting = 0;
    for (const g of gates) waiting += g.stats().waiting;
    if (waiting !== 0) throw new Error(`seed ${seed}: waiting=${waiting} after drain`);
    for (const h of inflight) h.release();
    return { seed, calls, ...terminals };
  })();
}

const results = [];
for (let seed = 1; seed <= 40; seed++) {
  results.push(await runOnly(seed));
}
async function runOnly(s) { return runOnce(s); }
for (const r of results) console.log(JSON.stringify(r));
console.log('ALL OK');

