import { createGate, QuotaExceededError } from './src/index.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function makeRng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 0x100000000;
  };
}

async function runOnce(seed) {
  const rnd = makeRng(seed);
  const root = createGate({ limit: 4, windowMs: 25, maxWaitMs: 70 });
  const mid = createGate({ limit: 3, windowMs: 40, maxWaitMs: 70, parent: root });
  const leaf = createGate({ limit: 2, windowMs: 55, maxWaitMs: 70, parent: mid });
  const side = createGate({ limit: 2, windowMs: 40, maxWaitMs: 70, parent: root });
  const gates = [root, mid, leaf, side];
  const handles = [];
  const pendingAcs = new Set();
  let calls = 0;
  const term = { granted: 0, refused: 0, expired: 0, cancelled: 0 };

  const check = (label) => {
    for (const g of gates) {
      const s = g.stats();
      for (const k of ['inFlight', 'waiting', 'granted', 'refused', 'expired', 'cancelled', 'reserved', 'rolledBack']) {
        if (typeof s[k] !== 'number' || !Number.isFinite(s[k]) || s[k] < 0) {
          throw new Error(`seed ${seed} ${label}: ${k}=${s[k]}`);
        }
      }
    }
  };

  const settle = (code) => {
    if (code === 'QUOTA_EXCEEDED') term.refused += 1;
    else if (code === 'WAIT_EXPIRED') term.expired += 1;
    else if (code === 'CANCELLED') term.cancelled += 1;
    else throw new Error('bad code ' + code);
  };

  const doCall = () => {
    const combo = rnd() < 0.35;
    const useSignal = rnd() < 0.5;
    const ac = useSignal ? new AbortController() : null;
    if (ac) pendingAcs.add(ac);
    let p;
    try {
      if (combo) {
        const n = 1 + Math.floor(rnd() * 2);
        const pool = [...gates];
        const members = [];
        const used = new Set();
        for (let i = 0; i < n; i++) {
          const g = pool[Math.floor(rnd() * pool.length)];
          if (used.has(g)) continue;
          used.add(g);
          members.push({ gate: g, units: 1 + Math.floor(rnd() * 3) });
        }
        if (members.length === 0) return;
        p = root.acquireAll(members, ac?.signal);
      } else {
        const g = gates[Math.floor(rnd() * gates.length)];
        const units = 1 + Math.floor(rnd() * 4);
        p = g.acquire(units, ac?.signal);
      }
    } catch (e) {
      if (e instanceof QuotaExceededError) throw e; // shouldn't happen synchronously
      return; // validation error: ignore, no counter
    }
    calls += 1;
    p.then(
      (h) => {
        term.granted += 1;
        handles.push(h);
      },
      (e) => settle(e.code),
    );
    if (ac && rnd() < 0.75) {
      setTimeout(() => {
        if (pendingAcs.has(ac)) {
          ac.abort();
          pendingAcs.delete(ac);
        }
      }, 1 + Math.floor(rnd() * 110));
    }
  };

  for (let i = 0; i < 80; i++) {
    const n = 1 + Math.floor(rnd() * 3);
    for (let j = 0; j < n; j++) doCall();
    await sleep(1 + Math.floor(rnd() * 30));
    while (handles.length > 0 && rnd() < 0.55) {
      const h = handles.shift();
      h.release();
      h.release();
    }
    if (rnd() < 0.08) {
      try {
        root.updateLimit(2 + Math.floor(rnd() * 5));
      } catch {}
    }
    if (rnd() < 0.05) {
      try {
        mid.updateMaxWaitMs([30, 70, 200][Math.floor(rnd() * 3)]);
      } catch {}
    }
    if (rnd() < 0.04) {
      try {
        leaf.reparent(side);
        await sleep(1);
        leaf.reparent(mid);
      } catch {}
    }
    check('mid');
  }

  await sleep(500);
  for (const ac of pendingAcs) ac.abort();
  await sleep(300);

  const total = term.granted + term.refused + term.expired + term.cancelled;
  if (total !== calls) {
    throw new Error(`seed ${seed}: UNSETTLED calls=${calls} term=${JSON.stringify(term)}`);
  }
  for (const g of gates) {
    const s = g.stats();
    if (s.waiting !== 0) throw new Error(`seed ${seed}: waiting=${s.waiting}`);
  }
  // After enough windows with no new calls, no uncommitted reservations remain
  await sleep(300);
  for (const g of gates) {
    const s = g.stats();
    if (s.reserved !== 0) throw new Error(`seed ${seed}: reserved=${s.reserved} on a gate`);
    if (s.waiting !== 0) throw new Error(`seed ${seed}: waiting2=${s.waiting}`);
  }
  while (handles.length) handles.shift().release();
  return { seed, calls, ...term };
}

let fails = 0;
for (let seed = 1; seed <= 50; seed++) {
  try {
    const r = await runOnce(seed);
    console.log('ok', JSON.stringify(r));
  } catch (e) {
    fails += 1;
    console.log('FAIL', e.message);
  }
}
console.log(fails === 0 ? 'ALL OK' : `${fails} FAILURES`);
process.exit(fails === 0 ? 0 : 1);

