        const units = 1 + Math.floor(rnd() * 4);
        p = g.acquire(units, ac?.signal);
      }
    } catch (e) {
      if (e instanceof QuotaExceededError) throw e; // shouldn't happen synchronously
      return; // validation error: ignore, no counter
    }
    calls += 1;
    p.then(
      (h) => {
        term.granted += 1;
        handles.push(h);
      },
      (e) => settle(e.code),
    );
    if (ac && rnd() < 0.75) {
      setTimeout(() => {
        if (pendingAcs.has(ac)) {
          ac.abort();
          pendingAcs.delete(ac);
        }
      }, 1 + Math.floor(rnd() * 110));
    }
  };

  for (let i = 0; i < 80; i++) {
    const n = 1 + Math.floor(rnd() * 3);
    for (let j = 0; j < n; j++) doCall();
    await sleep(1 + Math.floor(rnd() * 30));
    while (handles.length > 0 && rnd() < 0.55) {
      const h = handles.shift();
      h.release();
      h.release();
    }
    if (rnd() < 0.08) {
      try {
        root.updateLimit(2 + Math.floor(rnd() * 5));
      } catch {}
    }
    if (rnd() < 0.05) {
      try {
        mid.updateMaxWaitMs([30, 70, 200][Math.floor(rnd() * 3)]);
      } catch {}
    }
    if (rnd() < 0.04) {
      try {
        leaf.reparent(side);
        await sleep(1);
        leaf.reparent(mid);
      } catch {}
    }
    check('mid');
  }

  await sleep(500);
  for (const ac of pendingAcs) ac.abort();
  await sleep(300);

  const total = term.granted + term.refused + term.expired + term.cancelled;
  if (total !== calls) {
    throw new Error(`seed ${seed}: UNSETTLED calls=${calls} term=${JSON.stringify(term)}`);
  }
  for (const g of gates) {
    const s = g.stats();
    if (s.waiting !== 0) throw new Error(`seed ${seed}: waiting=${s.waiting}`);
  }
  // After enough windows with no new calls, no uncommitted reservations remain
  await sleep(300);
  for (const g of gates) {
    const s = g.stats();
    if (s.reserved !== 0) throw new Error(`seed ${seed}: reserved=${s.reserved} on a gate`);
    if (s.waiting !== 0) throw new Error(`seed ${seed}: waiting2=${s.waiting}`);
  }
  while (handles.length) handles.shift().release();
  return { seed, calls, ...term };
}

let fails = 0;
for (let seed = 1; seed <= 50; seed++) {
  try {
    const r = await runOnce(seed);
    console.log('ok', JSON.stringify(r));
  } catch (e) {
    fails += 1;
    console.log('FAIL', e.message);
  }
}
console.log(fails === 0 ? 'ALL OK' : `${fails} FAILURES`);
process.exit(fails === 0 ? 0 : 1);

