import { createGate } from './src/index.js';
const ka = setInterval(() => {}, 1000);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function snap(gates, label) {
  console.log(label, gates.map((g) => {
    const s = g.stats();
    return `{if:${s.inFlight} w:${s.waiting} r:${s.reserved} g:${s.granted} ref:${s.refused} e:${s.expired} c:${s.cancelled} rb:${s.rolledBack}}`;
  }).join(' '));
}

// Staggered window flips reclaim parts of a held over-limit reservation, then it expires.
{
  const root = createGate({ limit: 10, windowMs: 200, maxWaitMs: 5000 });
  const p = createGate({ limit: 2, windowMs: 40, maxWaitMs: 5000, parent: root });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 120, parent: p });
  await root.acquire(4); // pool 4/10
  const blocker = root.acquire(7).catch(() => {}); // head, can't gather, queues
  // a's request: own2 + p lend2 + pool1 = 5; 4+5<=10 gathers, waits behind blocker
  const mine = a.acquire(5).then(() => 'g', (e) => e.code);
  snap([root, p, a], 'queued:        ');
  await sleep(50); // p window flips: uncommitted lend (2) reclaimed
  snap([root, p, a], 'after p flip:  ');
  await sleep(130); // a expires at 120 (deadline), before pool flip at 200
  const res = await mine;
  snap([root, p, a], 'after expire:  ');
  console.log('mine settled:', res);
  blocker.catch(() => {});
  await sleep(400);
  snap([root, p, a], 'after drain:   ');
}

clearInterval(ka);

