import { createGate, QuotaExceededError } from './src/index.js';
const ka = setInterval(() => {}, 500);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Collision stress: windowMs == maxWaitMs so expiry and the flip collide;
// aborts are fired at jittered times around the flip boundary.
let problems = 0;
for (let iter = 0; iter < 200; iter++) {
  const W = 20 + (iter % 5) * 5;
  const root = createGate({ limit: 2, windowMs: W, maxWaitMs: W });
  const a = createGate({ limit: 1, windowMs: W, maxWaitMs: W, parent: root });
  const gates = [root, a];
  const term = { granted: 0, refused: 0, expired: 0, cancelled: 0 };
  let calls = 0;
  const handles = [];
  const acs = [];

  const fire = (p) => {
    calls++;
    p.then((h) => { term.granted++; handles.push(h); },
      (e) => { term[e.code === 'QUOTA_EXCEEDED' ? 'refused' : e.code === 'WAIT_EXPIRED' ? 'expired' : 'cancelled']++; });
  };

  // saturate
  fire(root.acquire(2));
  // a mix queued exactly as the window starts
  for (let i = 0; i < 6; i++) {
    const g = gates[i % 2];
    const ac = new AbortController();
    acs.push(ac);
    if (i % 3 === 0) {
      fire(root.acquireAll([{ gate: a, units: 1 + (i % 2) }], ac.signal));
    } else {
      fire(g.acquire(1, ac.signal));
    }
    // abort some at the collision boundary +/- a few ms
    if (i % 2 === 0) setTimeout(() => ac.abort(), W + ((i % 3) - 1));
  }

  await sleep(W * 4 + 30);
  while (handles.length) handles.shift().release();
  await sleep(W + 30);

  const tot = term.granted + term.refused + term.expired + term.cancelled;
  for (const g of gates) {
    const s = g.stats();
    if (s.waiting !== 0 || s.reserved !== 0) {
      console.log(`iter ${iter}: LEAK`, JSON.stringify(s), JSON.stringify(term));
      problems++;
    }
  }
  if (tot !== calls) {
    console.log(`iter ${iter}: UNSETTLED calls=${calls} term=${JSON.stringify(term)}`);
    problems++;
  }
}
console.log(problems === 0 ? 'COLLISION ALL OK' : `${problems} PROBLEMS`);
clearInterval(ka);
process.exit(problems === 0 ? 0 : 1);

