const ka = setInterval(() => {}, 500);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Combo entered via root R, member is child a. Then a reparents to a new family.
// All members move but the owner (R) stays in the old family.
const R = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000 });
const a = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000, parent: R });
const N = createGate({ limit: 4, windowMs: 30, maxWaitMs: 5000 });

await R.acquire(1); // R pool full
const p = R.acquireAll([{ gate: a, units: 1 }]); // owner=R, member=a; queues
console.log('before reparent R:', JSON.stringify(R.stats()));
console.log('before reparent a:', JSON.stringify(a.stats()));

a.reparent(N); // moves a (the only member) into family N; owner R stays
console.log('after reparent R:', JSON.stringify(R.stats()));
console.log('after reparent N:', JSON.stringify(N.stats()));
console.log('after reparent a:', JSON.stringify(a.stats()));

try {
  const h = await p;
  console.log('combo settled GRANTED');
  h.release();
} catch (e) {
  console.log('combo settled', e.code);
}
await sleep(50);
console.log('final R:', JSON.stringify(R.stats()));
console.log('final N:', JSON.stringify(N.stats()));
console.log('final a:', JSON.stringify(a.stats()));
clearInterval(ka);

