import { createGate } from './src/index.js';
const ka = setInterval(() => {}, 500);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const j = (g) => JSON.stringify(g.stats());

// SYMMETRIC: owner moves, member (sibling) stays in old family.
// a.acquireAll([b]); then a.reparent(N). Owner a -> N, member b stays old.
{
  const R = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: R });
  const b = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: R });
  const N = createGate({ limit: 5, windowMs: 30, maxWaitMs: 5000 });
  await R.acquire(4); // R pool 4/5
  const p = a.acquireAll([{ gate: b, units: 1 }]); // 4+1=5 gathers; owner=a moves later, member b stays
  a.reparent(N); // owner moves to N; member b does not
  console.log('after reparent R:', j(R));
  console.log('after reparent N:', j(N));
  let res;
  try { const h = await p; res='GRANTED'; h.release(); } catch(e){ res=e.code; }
  console.log('combo ->', res);
  await sleep(60);
  console.log('final R:', j(R));
  console.log('final N:', j(N));
  console.log('final a:', j(a));
  console.log('final b:', j(b));
}

console.log('--- liveQueued leak user-visible impact ---');
// After the owner-stays/member-moves combo expires, does N still grant immediately?
{
  const R = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 30 });
  const a = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 30, parent: R });
  const N = createGate({ limit: 4, windowMs: 10000, maxWaitMs: 5000 });
  await R.acquire(1);
  const p = R.acquireAll([{ gate: a, units: 1 }]).catch(e=>e.code);
  a.reparent(N);
  await sleep(80); // combo expires in R while living in N.queue
  console.log('R after expire:', j(R));
  console.log('N after expire:', j(N));
  // N has a totally free pool; a brand new immediate request should GRANT now.
  const before = N.stats().granted;
  const h = await N.acquire(1); // should grant immediately (no waiters)
  console.log('N immediate grant delta:', N.stats().granted - before, '(expect 1)');
  console.log('N inFlight:', N.stats().inFlight, 'waiting:', N.stats().waiting);
  h.release();
}
clearInterval(ka);

