input.new_string:
  // A combo is coherent only while its owner (the entry-point gate that
  // gathers against entry.owner.root) and EVERY member end in one family.
  // A split between the owner and the members is just as unreservable as
  // members split among themselves: the gather would run against a pool
  // the members no longer share (or vice versa), so it is refused whole.
  // This keeps every entry in family X's queue owned by a gate in X.
  const ownerMoved = moved.has(entry.owner);
  let inMoved = 0;
  for (const g of entry.comboGates) if (moved.has(g)) inMoved += 1;
  if (ownerMoved && inMoved === entry.comboGates.length) {
    whollyMoved.push(entry);
  } else if (!ownerMoved && inMoved === 0) {
    stayingCombos.push(entry);
  } else {
    straddlers.push(entry);
  }
}

