import { createGate, QuotaExceededError } from './src/index.js';
const ka = setInterval(() => {}, 200);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function rng(seed) { let s = seed >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 0x100000000; }; }

async function once(seed) {
  const rnd = rng(seed);
  // Two families; gates frequently migrate between them.
  const R = createGate({ limit: 3, windowMs: 25, maxWaitMs: 120 });
  const N = createGate({ limit: 3, windowMs: 35, maxWaitMs: 120 });
  const fam = [
    R,
    createGate({ limit: 2, windowMs: 30, maxWaitMs: 120, parent: R }),
    createGate({ limit: 2, windowMs: 40, maxWaitMs: 120, parent: R }),
    N,
    createGate({ limit: 2, windowMs: 30, maxWaitMs: 120, parent: N }),
  ];
  const all = [R, fam[1], fam[2], N, fam[4]];
  let calls = 0;
  const term = { granted: 0, refused: 0, expired: 0, cancelled: 0 };
  const handles = [];
  const acs = new Set();

  const rootOf = (g) => all.includes(g) ? null : null; // unused
  const check = (label) => {
    for (const g of all) {
      const s = g.stats();
      for (const k of ['inFlight','waiting','granted','refused','expired','cancelled','reserved']) {
        if (!Number.isFinite(s[k]) || s[k] < 0) throw new Error(`seed ${seed} ${label} ${k}=${s[k]}`);
      }
    }
  };

  const fire = (p) => { calls++; p.then((h)=>{term.granted++;handles.push(h);},
    (e)=>{ term[e.code==='QUOTA_EXCEEDED'?'refused':e.code==='WAIT_EXPIRED'?'expired':'cancelled']++; }); };

  for (let i = 0; i < 120; i++) {
    // 1-3 calls: singles and combos entered through a random owner gate
    const n = 1 + Math.floor(rnd()*3);
    for (let k=0;k<n;k++) {
      const owner = all[Math.floor(rnd()*all.length)];
      const ac = rnd()<0.4 ? new AbortController() : null;
      if (ac) { acs.add(ac); setTimeout(()=>{ if(acs.has(ac)){ac.abort();acs.delete(ac);} }, 1+Math.floor(rnd()*150)); }
      if (rnd()<0.5) {
        const g = all[Math.floor(rnd()*all.length)];
        // only call on same-family owner/gate combos to avoid the validation RangeError noise
        if (g.root !== owner.root) continue;
        fire(owner === g ? g.acquire(1+Math.floor(rnd()*3), ac?.signal)
                         : owner.acquireAll([{gate:g,units:1+Math.floor(rnd()*2)}], ac?.signal));
      } else {
        // combo of 1-2 same-family members entered through `owner` (possibly not a member)
        const same = all.filter((g)=>g.root===owner.root);
        const m1 = same[Math.floor(rnd()*same.length)];
        const members=[{gate:m1,units:1+Math.floor(rnd()*2)}];
        if (rnd()<0.4) {
          const m2 = same[Math.floor(rnd()*same.length)];
          if (m2!==m1 && !m1.parent && true) {} // ancestor guard is module's job; pick sibling-ish
          if (m2!==m1 && m2.parent!==m1 && m1.parent!==m2) members.push({gate:m2,units:1+Math.floor(rnd()*2)});
        }
        try { fire(owner.acquireAll(members, ac?.signal)); } catch { /* validation: ignore */ calls--; }
      }
    }
    await sleep(1+Math.floor(rnd()*25));
    // release some handles
    while (handles.length && rnd()<0.5) { const h=handles.shift(); h.release(); h.release(); }
    // reparent a gate to the other family (cross-family), retrying on rejection
    if (rnd()<0.18) {
      const g = all[Math.floor(rnd()*all.length)];
      const target = g.root === R ? N : R;
      try {
        // limit must not exceed new parent's; roots can reparent under target
        if (g === R || g === N) {
          if (g.limit <= target.limit) g.reparent(target);
        } else {
          // find a parent in target family with a large enough limit
          if (g.limit <= target.limit) g.reparent(target);
        }
      } catch (e) { /* QUOTA_EXCEEDED move or hierarchy: ignored */ }
    }
    check('mid');
  }
  await sleep(700);
  for (const ac of acs) ac.abort();
  await sleep(400);
  const tot = term.granted+term.refused+term.expired+term.cancelled;
  if (tot !== calls) throw new Error(`seed ${seed}: UNSETTLED ${calls} vs ${JSON.stringify(term)}`);
  for (const g of all) {
    const s=g.stats();
    if (s.waiting!==0) throw new Error(`seed ${seed}: waiting ${s.waiting}`);
  }
  while(handles.length) handles.shift().release();
  return { seed, calls, ...term };
}

let fails=0;
for (let seed=1; seed<=30; seed++) {
  try { console.log('ok', JSON.stringify(await once(seed))); }
  catch(e){ fails++; console.log('FAIL', e.message); }
}
console.log(fails===0?'CROSS-FAMILY ALL OK':`${fails} FAILURES`);
clearInterval(ka);
process.exit(fails?1:0);

